import itertools, sys
N=6
cells=range(N*N)
# precompute moves
moves={c:[] for c in cells}
for r in range(N):
 for c in range(N):
  a=r* N + c
  for dr,dc in [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]:
   nr, nc = r+dr, c+dc
   if 0<=nr<N and 0<=nc<N:
    moves[a].append(nr*N+nc)
# backtrack with constraints
fixed={3:17,6:24,17:30,19:6,29:25,32:21,34:23}
solution=[None]*36
solution[0]=0
used=set([0])
for i,v in fixed.items():
    solution[i]=v
    used.add(v)

def backtrack(pos):
    if pos==36:
        return solution
    if solution[pos] is not None:
        # check move from previous
        if solution[pos] not in moves[solution[pos-1]]:
            return None
        return backtrack(pos+1)
    prev=solution[pos-1]
    for nxt in moves[prev]:
        if nxt in used:
            continue
        # if nxt is fixed later at some index, must match
        if nxt in fixed.values():
            # find its fixed index
            idx=[k for k,v in fixed.items() if v==nxt][0]
            if idx!=pos:
                continue
        solution[pos]=nxt
        used.add(nxt)
        res=backtrack(pos+1)
        if res:
            return res
        used.remove(nxt)
        solution[pos]=None
    return None

